  ('amazon_mgm', 'Amazon MGM Studios', 'estudio_eua', array['now']::text[], '{"estilo":"duro","prioridades":["multiplataforma","preco"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Nicole Avery","cargo":"Diretora de licenciamento","estilo":"prioriza o Prime Video","ficticio":true}'::jsonb, 'media', 'Memória: dona do acervo MGM, incluindo o formato The Apprentice.', '2026-lote2b'),
