  ('lionsgate', 'Lionsgate', 'estudio_eua', array['now']::text[], '{"estilo":"leiloeiro","prioridades":["preco","pacote"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Ryan Mercer","cargo":"Vice-presidente de vendas internacionais","estilo":"negocia franquias inteiras","ficticio":true}'::jsonb, 'alta', 'Memória: estúdio de Jogos Vorazes, John Wick e Crepúsculo (via Summit).', '2026-lote2b'),
  ('globo_filmes', 'Globo Filmes', 'emissora', array['now']::text[], '{"estilo":"duro","prioridades":["exclusividade","janela_propria"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Renato Valadares","cargo":"Gerente de negócios","estilo":"só negocia se a Globo abrir mão","ficticio":true}'::jsonb, 'media', 'Memória: braço de cinema da Globo; coproduções da Globo Filmes costumam ter a primeira janela de TV aberta na própria Globo (direito 2633).', '2026-lote2b'),
